/*
 * Not jQuery Migrate. Hostinger's CDN can still hand out the old WordPress
 * home page for takees.in/, and that page loads this address right after
 * jquery.min.js (which some CDN servers still hold as the real jQuery).
 * Send the visitor on to the current home page; js/main.js tidies the
 * address back to /. Safe to delete once the CDN cache has been purged.
 */
if (window.location.search !== '?home') {
  document.documentElement.style.visibility = 'hidden';
  window.location.replace('/?home');
}
